const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    const line = line.trim();
    // Parse the input: number followed by a letter
    const match = line.match(/^(\d+)([a-f])$/);
    if (!match) return;

    const n = BigInt(match[1]);
    const s = match[2];

    // Determine which attendant serves this row and the order
    // Attendant 1 serves rows: 1, 2, 5, 6, 9, 10, ...
    // Attendant 2 serves rows: 3, 4, 7, 8, 11, 12, ...

    // The pattern of rows served:
    // Step 1: rows 1, 3
    // Step 2: rows 2, 4
    // Step 3: rows 5, 7
    // Step 4: rows 6, 8
    // Step 5: rows 9, 11
    // Step 6: rows 10, 12
    // ...

    // Each "cycle" consists of 4 rows: two steps of 1 row forward, then two steps of 3 rows forward? 
    // Let's re-analyze the movement:
    // Start: Att1 at row 1, Att2 at row 3
    // After serving rows 1 and 3 (6 seconds), they move 1 row forward: Att1 at row 2, Att2 at row 4
    // After serving rows 2 and 4 (6 seconds), they move 3 rows forward: Att1 at row 5, Att2 at row 7
    // After serving rows 5 and 7 (6 seconds), they move 1 row forward: Att1 at row 6, Att2 at row 8
    // After serving rows 6 and 8 (6 seconds), they move 3 rows forward: Att1 at row 9, Att2 at row 11
    // ...

    // So the sequence of row pairs is:
    // (1,3), (2,4), (5,7), (6,8), (9,11), (10,12), ...

    // For a given row n, we need to find:
    // 1. Which attendant serves it (1 or 2)
    // 2. How many complete pairs have been served before this pair
    // 3. The position of the seat within the row

    // Let's figure out the pattern of rows for each attendant:
    // Attendant 1: 1, 2, 5, 6, 9, 10, 13, 14, ...
    // Attendant 2: 3, 4, 7, 8, 11, 12, 15, 16, ...

    // For Attendant 1: rows are of the form 4k+1 and 4k+2 for k >= 0
    // For Attendant 2: rows are of the form 4k+3 and 4k+4 for k >= 0

    // Let's determine which attendant serves row n:
    const mod4 = n % 4n;
    let attendant;
    let k; // the cycle index

    if (mod4 === 1n || mod4 === 2n) {
        attendant = 1;
        // n = 4k + 1 or 4k + 2
        // If n % 4 == 1, then k = (n-1)/4
        // If n % 4 == 2, then k = (n-2)/4
        if (mod4 === 1n) {
            k = (n - 1n) / 4n;
        } else {
            k = (n - 2n) / 4n;
        }
    } else {
        attendant = 2;
        // n = 4k + 3 or 4k + 4
        // If n % 4 == 3, then k = (n-3)/4
        // If n % 4 == 0, then k = (n-4)/4
        if (mod4 === 3n) {
            k = (n - 3n) / 4n;
        } else {
            k = (n - 4n) / 4n;
        }
    }

    // Now, how many complete pairs have been served before the pair that includes row n?
    // Each cycle k has two pairs:
    // Pair 1 of cycle k: rows (4k+1, 4k+3)
    // Pair 2 of cycle k: rows (4k+2, 4k+4)

    // If attendant is 1:
    //   If mod4 == 1, it's the first pair of cycle k
    //   If mod4 == 2, it's the second pair of cycle k
    // If attendant is 2:
    //   If mod4 == 3, it's the first pair of cycle k
    //   If mod4 == 0, it's the second pair of cycle k

    let pairIndexInCycle;
    if (attendant === 1) {
        if (mod4 === 1n) {
            pairIndexInCycle = 0;
        } else {
            pairIndexInCycle = 1;
        }
    } else {
        if (mod4 === 3n) {
            pairIndexInCycle = 0;
        } else {
            pairIndexInCycle = 1;
        }
    }

    // Total number of complete pairs served before this pair:
    // Each cycle has 2 pairs. Before cycle k, there are k cycles, so 2k pairs.
    // Within cycle k, before pairIndexInCycle, there are pairIndexInCycle pairs.
    const totalPairsBefore = 2n * k + BigInt(pairIndexInCycle);

    // Time to serve all previous pairs: each pair takes 6 seconds (3 seats right + 3 seats left)
    const timeForPreviousPairs = totalPairsBefore * 6n;

    // Time to move to the current pair:
    // The movement happens between pairs.
    // After pair 0 (rows 1,3), move 1 row (1 sec)
    // After pair 1 (rows 2,4), move 3 rows (3 sec)
    // After pair 2 (rows 5,7), move 1 row (1 sec)
    // After pair 3 (rows 6,8), move 3 rows (3 sec)
    // ...

    // The movement time after pair i:
    // If i is even (0, 2, 4, ...), move 1 row (1 sec)
    // If i is odd (1, 3, 5, ...), move 3 rows (3 sec)

    // So the total movement time before the current pair (which is pair totalPairsBefore):
    // We need to sum the movement times after pairs 0, 1, ..., totalPairsBefore-1

    let movementTime = 0n;
    // For each pair j from 0 to totalPairsBefore-1, add the movement time after pair j
    // This is a sum of alternating 1s and 3s.
    // Number of 1s: ceil(totalPairsBefore / 2)
    // Number of 3s: floor(totalPairsBefore / 2)

    const numOnes = (totalPairsBefore + 1n) / 2n;
    const numThrees = totalPairsBefore / 2n;

    movementTime = numOnes * 1n + numThrees * 3n;

    // Now, within the current pair, how long does it take to serve Vasya's seat?
    // The attendant serves right side first (f, e, d) then left side (c, b, a)
    // Seat order: f=1, e=2, d=3, c=4, b=5, a=6

    let seatTime;
    switch (s) {
        case 'f': seatTime = 1n; break;
        case 'e': seatTime = 2n; break;
        case 'd': seatTime = 3n; break;
        case 'c': seatTime = 4n; break;
        case 'b': seatTime = 5n; break;
        case 'a': seatTime = 6n; break;
        default: seatTime = 0n;
    }

    const totalTime = timeForPreviousPairs + movementTime + seatTime;

    console.log(totalTime.toString());
});
