const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    const n = BigInt(line.slice(0, -1));
    const s = line.slice(-1);

    // Seat order: f, e, d, c, b, a
    // f: 1, e: 2, d: 3, c: 4, b: 5, a: 6
    const seatOrder = { 'f': 1, 'e': 2, 'd': 3, 'c': 4, 'b': 5, 'a': 6 };
    const seatNum = seatOrder[s];

    // Determine which attendant serves row n
    // Attendant 1 serves rows: 1, 2, 5, 6, 9, 10, ...
    // Attendant 2 serves rows: 3, 4, 7, 8, 11, 12, ...
    // Pattern: rows are served in pairs (1,3), (2,4), (5,7), (6,8), ...
    // Actually, let's think about the movement pattern.
    // Start: A1 at row 1, A2 at row 3
    // Move 1 row forward: A1 at row 2, A2 at row 4
    // Move 3 rows forward: A1 at row 5, A2 at row 7
    // Move 1 row forward: A1 at row 6, A2 at row 8
    // Move 3 rows forward: A1 at row 9, A2 at row 11
    // ...

    // The rows served by A1: 1, 2, 5, 6, 9, 10, 13, 14, ...
    // The rows served by A2: 3, 4, 7, 8, 11, 12, 15, 16, ...

    // Let's find a pattern.
    // For row n, we need to figure out how many "cycles" have passed and where in the cycle we are.
    // Each cycle consists of:
    // - Serve 2 rows (A1 and A2 each serve 1 row): takes 6 seconds (6 passengers per row, but they work in parallel)
    //   Wait, no. Each attendant serves 6 passengers in 6 seconds. They work in parallel.
    //   So serving one row takes 6 seconds.
    // - Move 1 row forward: takes 1 second
    // - Serve 2 rows: takes 6 seconds
    // - Move 3 rows forward: takes 3 seconds
    // - Repeat

    // So the pattern of row numbers served by A1 is: 1, 2, 5, 6, 9, 10, 13, 14, ...
    // And by A2 is: 3, 4, 7, 8, 11, 12, 15, 16, ...

    // Let's group rows in blocks of 4:
    // Block 0: rows 1, 2, 3, 4
    // Block 1: rows 5, 6, 7, 8
    // Block 2: rows 9, 10, 11, 12
    // ...
    // Block k: rows 4k+1, 4k+2, 4k+3, 4k+4

    // In each block:
    // - First, A1 serves row 4k+1, A2 serves row 4k+3 (takes 6 seconds)
    // - Then move 1 row forward (takes 1 second)
    // - Then A1 serves row 4k+2, A2 serves row 4k+4 (takes 6 seconds)
    // - Then move 3 rows forward (takes 3 seconds)
    // Total time per block: 6 + 1 + 6 + 3 = 16 seconds

    // Now, for a given row n, let's find which block it's in and which position within the block.
    // n is 1-indexed.
    // block = floor((n - 1) / 4)
    // pos = (n - 1) % 4  (0-indexed: 0, 1, 2, 3)

    // If pos == 0: row is 4*block + 1, served by A1 in first serving phase
    // If pos == 1: row is 4*block + 2, served by A1 in second serving phase
    // If pos == 2: row is 4*block + 3, served by A2 in first serving phase
    // If pos == 3: row is 4*block + 4, served by A2 in second serving phase

    const block = (n - 1n) / 4n;
    const pos = (n - 1n) % 4n;

    // Time before this block starts: block * 16
    let time = block * 16n;

    if (pos === 0n) {
        // A1 serves row 4*block + 1
        // This is the first serving phase of the block
        // Time to reach this passenger: time + seatNum
        time = time + BigInt(seatNum);
    } else if (pos === 1n) {
        // A1 serves row 4*block + 2
        // This is the second serving phase of the block
        // Before this: 6 seconds (first serving) + 1 second (move)
