    const seatOrder = { 'f': 1, 'e': 2, 'd': 3, 'a': 4, 'b': 5, 'c': 6 };
    const seatNum = seatOrder[s];

    // The attendants serve rows in pairs: (1,3), (2,4), (5,7), (6,8), (9,11), ...
    // Pattern: 
    // Step 1: rows 1 and 3
    // Step 2: rows 2 and 4
    // Step 3: rows 5 and 7
    // Step 4: rows 6 and 8
    // Step 5: rows 9 and 11
    // ...
    // 
    // Let's figure out which "step" row n belongs to.
    // The rows served in each step are:
    // Step 1: 1, 3
    // Step 2: 2, 4
    // Step 3: 5, 7
    // Step 4: 6, 8
    // Step 5: 9, 11
    // Step 6: 10, 12
    //
    // Notice that steps come in groups of 2:
    // Group 1 (steps 1-2): rows 1,2,3,4
    // Group 2 (steps 3-4): rows 5,6,7,8
    // Group 3 (steps 5-6): rows 9,10,11,12
    // ...
    // Group k (steps 2k-1, 2k): rows 4(k-1)+1, 4(k-1)+2, 4(k-1)+3, 4(k-1)+4
    //
    // So for a given row n, we can find which group it belongs to.
    // Group index g = ceil(n / 4) = Math.ceil(n / 4)
    // But we need to be careful with BigInt.

    // Let's compute the group number:
    // g = Math.floor((n - 1) / 4n) + 1n
    const g = (n - 1n) / 4n + 1n;

    // Within the group, the rows are:
    // Row 4(g-1)+1, 4(g-1)+2, 4(g-1)+3, 4(g-1)+4
    // Let r = n - (4(g-1))  => r is 1, 2, 3, or 4
    const r = n - (4n * (g - 1n));

    // Now, which step does this row belong to?
    // If r is 1 or 3, it's the first row in the step (served by first attendant)
    // If r is 2 or 4, it's the second row in the step (served by second attendant)
    //
    // Step number within the group:
    // If r is 1 or 3: step = 2(g-1) + 1
    // If r is 2 or 4: step = 2(g-1) + 2

    let step;
    if (r === 1n || r === 3n) {
        step = 2n * (g - 1n) + 1n;
    } else {
        step = 2n * (g - 1n) + 2n;
    }

    // Now, let's calculate the total time.
    // Before step `step`, there have been `step - 1` steps completed.
